def number_to_words(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool) or not (0 <= n <= 999999):
        raise ValueError("Input must be an integer between 0 and 999999 inclusive.")

    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def convert_below_thousand(num: int) -> list[str]:
        parts = []
        hundreds = num // 100
        remainder = num % 100

        if hundreds > 0:
            parts.append(f"{ones[hundreds]} hundred")

        if remainder > 0:
            if remainder < 20:
                parts.append(ones[remainder])
            else:
                t = remainder // 10
                u = remainder % 10
                if u > 0:
                    parts.append(f"{tens[t]}-{ones[u]}")
                else:
                    parts.append(tens[t])

        return parts

    thousands_part = n // 1000
    remainder_part = n % 1000

    result = []
    if thousands_part > 0:
        result.extend(convert_below_thousand(thousands_part))
        result.append("thousand")

    if remainder_part > 0:
        result.extend(convert_below_thousand(remainder_part))

    return " ".join(result)
